import {TUTORIAL_MISSIONS,tutorialMission,tutorialObjective} from './tutorial.js?v=197';
import {ACTIONS,COUNTRY} from './data.js?v=197';
import {proofTitle} from './intelligence.js?v=197';
import {button,brand,esc,portrait,icon,statlines,flag} from './ui.js?v=197';
import {statusBadge} from './presentation.js?v=197';
const header=controls=>`<header class="training-header">${brand()}<span class="training-label">ACADÉMIE / SIGMA</span><nav aria-label="Navigation de la formation">${controls}</nav></header>`;
export function tutorialMenu(progress){return `<div class="training-page">${header(button('Menu principal','main-menu'))}<main class="training-menu"><span class="eyebrow">DOSSIER D’INITIATION / 2040</span><h1>Opération <em>Filigrane</em></h1><p class="training-intro">Un contact. Deux documents suspects. Une arrestation à préparer.<br>Apprenez les bases en trois petites missions reliées par une histoire.</p><div class="training-promises"><span>${icon('people')} Aucun joueur PNJ</span><span>${icon('check')} Réussites scénarisées</span><span>${icon('file')} Campagne conservée</span></div>${progress.warning?'<p class="notice warning">Une sauvegarde d’exercice n’a pas pu être reprise. Vous pouvez relancer cette mission ; les autres progrès sont conservés.</p>':''}<div class="training-missions">${TUTORIAL_MISSIONS.map(m=>{const saved=progress.sessions[m.id],status=saved&&tutorialObjective(saved),resume=saved&&!status.done&&!status.failed;return `<article class="training-mission"><span class="training-number">${m.number}</span><div class="training-mission-meta">${m.duration} · ${m.agents} agent${m.agents>1?'s':''}</div><h2>${m.title}</h2><p>${m.brief}</p><p class="training-skills">${m.skills}</p><div class="training-mission-bottom">${button(resume?'Reprendre · tour '+saved.turn:progress.completed.includes(m.id)?'Rejouer la mission':'Commencer','tutorial-start','primary',`data-id="${m.id}"`)}<small>${progress.completed.includes(m.id)?'✓ Mission accomplie':status?.failed?'À réessayer':'Mission indépendante'}</small></div></article>`;}).join('')}</div><p class="training-footnote">Toutes les missions sont accessibles et rejouables séparément. Vos progrès sont enregistrés dans ce navigateur, à part de la campagne. Les durées, prérequis et coûts d’énergie sont ceux du jeu ; les actions autorisées réussissent à 100 % pendant cette formation.</p></main></div>`;}
export function tutorialScreen(s,saveWarning=false){
 const m=tutorialMission(s.tutorial.mission),o=tutorialObjective(s),f=s.factions.FR,k=f.known.s0,finished=o.done||o.failed,next=TUTORIAL_MISSIONS[TUTORIAL_MISSIONS.indexOf(m)+1];
 const busy=s.agents.some(a=>a.task),ready=o.orders.filter(order=>!s.agents.find(a=>a.id===order.agentId)?.task);
 const goals=m.goals.map((label,i)=>{let done=i<o.step;if(m.id==='arrest')done=[!!k.prepared,!!f.authorized.DE,k.locationUntil>=s.turn,s.suspects[0].arrested][i];return `<li class="${done?'is-done':''}" ${!done&&i===o.step?'aria-current="step"':''}><span>${done?'✓':String(i+1).padStart(2,'0')}</span>${label}</li>`;}).join('');
 const latest=(s.turnActivities||[]).filter(r=>r.type);
 return `<div class="training-page">${header(button('Les missions','tutorial-menu')+button('Recommencer','tutorial-restart','small')+button('Aide','tutorial-help','small'))}<main class="training-workspace"><div class="training-topline"><span class="eyebrow">FILIGRANE / MISSION ${m.number}</span><span>TOUR <strong>${s.turn}</strong>${m.id==='arrest'?' · Départ de la cible : fin T6':''}</span></div><h1>${m.title}</h1><p class="training-scenario-note">Simulation guidée · Aucun joueur PNJ · Réussite garantie des actions autorisées</p>${saveWarning?'<p class="notice warning" role="alert">Progression non enregistrée dans ce navigateur. Gardez cette page ouverte pour poursuivre l’exercice.</p>':''}
 <div class="training-layout"><aside class="training-brief"><span class="eyebrow">CANAL / CONTRÔLE</span><p class="training-dialogue">« ${esc(m.brief)} »</p><ol class="training-checklist" aria-label="Objectifs de la mission">${goals}</ol><details><summary>Ce que vous apprenez</summary><p>${esc(m.lesson)}</p></details></aside><section class="training-operations">
 <section class="training-objective ${finished?'training-result':''}" aria-live="polite" tabindex="-1"><span class="eyebrow">${o.done?'MISSION ACCOMPLIE':o.failed?'MISSION À REJOUER':'VOTRE OBJECTIF'}</span><h2>${esc(o.title)}</h2><p>${esc(o.text)}</p>${finished?`<p>${o.done?esc(m.next):'Votre campagne et les autres missions ne sont pas affectées.'}</p><div class="training-result-actions">${o.done&&next?button('Mission suivante · '+next.number,'tutorial-start','primary',`data-id="${next.id}"`):button(o.failed?'Réessayer cette mission':'Retour aux missions',o.failed?'tutorial-restart-confirm':'tutorial-menu','primary')}${button('Menu principal','main-menu')}</div>`:`<div class="training-turn-control"><span>${busy?'Un ordre est en cours ou planifié. Terminez le tour pour le faire avancer.':'Choisissez l’agent indiqué ci-dessous, puis confirmez son ordre.'}</span>${button('Terminer le tour '+icon('arrow'),'advance','primary '+(busy?'tutorial-focus':''),!busy&&m.id!=='arrest'?'disabled':'')}</div>${busy&&ready.length?'<p class="training-tip">Vous pouvez aussi affecter l’autre agent avant de terminer le tour.</p>':''}${!busy&&m.id==='arrest'?'<small>Attendre sans ordre consomme aussi un tour de la fenêtre d’intervention.</small>':''}`}</section>
 <section aria-label="Votre équipe"><h2 class="training-section-title">Votre équipe <span>${m.place}</span></h2><div class="training-agents">${s.agents.map(a=>{const suggested=o.orders.find(x=>x.agentId===a.id),available=!finished&&!a.task&&!!suggested;return `<article class="training-agent ${available?'is-suggested':''}">${portrait(a)}<div class="training-agent-copy"><span class="eyebrow">${flag(a.country)} ${COUNTRY[a.country].city}${a.country===a.faction?' · QG':' · TERRAIN'}</span><h3>${esc(a.name)}</h3><p>${esc(a.role)}</p>${statlines(a)}<p class="training-energy">Énergie <strong>${100-a.fatigue}/100</strong></p>${statusBadge(a)}${a.task?`<p>${esc(ACTIONS[a.task.type].name)} · ${a.task.remaining} tour(s) restant(s)</p>`:''}${available?button('Affecter : '+ACTIONS[suggested.type].name,'tutorial-agent','wide tutorial-focus',`data-id="${a.id}"`):a.task?button('Consulter / annuler l’ordre','agent','wide small',`data-id="${a.id}"`):'<small class="muted">'+(finished?'Exercice terminé':'En attente · un autre agent intervient')+'</small>'}</div></article>`;}).join('')}</div></section>
 ${m.id!=='contact'?`<section class="training-dossier" aria-label="Dossier Vesper"><h2>Dossier / Vesper</h2><div class="training-dossier-status"><span>${flag('DE')} Berlin</span><span>Accès ouvert</span><span>${k.prepared?'✓ Dossier préparé':'Dossier non préparé'}</span><span>${f.authorized.DE?'✓ Mandat obtenu':'Sans mandat'}</span><span>${k.locationUntil>=s.turn?'Position valide · fin T'+k.locationUntil+' incluse':k.locationUntil?'Position périmée':'Position à confirmer'}</span></div>${f.evidence.length?`<ul class="training-proofs">${f.evidence.map(e=>`<li class="${e.contested?'is-false':e.verified?'is-verified':''}"><span>${esc(proofTitle(s.proofs.find(p=>p.id===e.id)))}</span><strong>${e.contested?'Falsification écartée':e.verified?'Preuve vérifiée':'Pièce brute · à vérifier'}</strong></li>`).join('')}</ul>`:'<p>Aucune preuve recueillie. Les pièces apparaîtront ici après la collecte.</p>'}</section>`:''}
 ${latest.length?`<section class="training-recap" aria-label="Résultats du dernier tour"><h2>Résultats / Tour ${s.turn-1}</h2>${latest.map(r=>`<article><strong>${esc(r.agent)} · ${esc(ACTIONS[r.type].name)}</strong><span>${esc(r.status)}</span>${r.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</article>`).join('')}</section>`:''}
 </section></div></main><footer class="training-footer">SIGMA NETWORK / ACADÉMIE <span>Progression séparée · Campagne conservée</span></footer></div>`;
}
